// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, uint256 deposit) public {
        deposit = bound(deposit, 1, 1 ether);
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        vm.deal(address(this), deposit);
        (bool sent,) = address(c).call{value: deposit}("");
        require(sent, "deposit failed");

        uint256 before = address(c).balance;
        require(before == deposit);

        vm.deal(caller, 0);
        vm.prank(caller);

        bool ok;
        try c.withdrawAll(payable(caller)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
